mapper.select:
SELECT a.agent_id, a.agent_code, a.agent_name, a.display_alias, a.agent_type, a.status, a.revision, a.latest_version_id, a.latest_version_no, a.latest_readiness, COALESCE(lv.description, '') AS description, a.current_release_id, r.release_no AS current_release_no, r.published_at AS current_release_at, CASE WHEN a.agent_type != 'MASTER' THEN NULL WHEN a.current_release_id IS NULL THEN 'UNPUBLISHED' WHEN r.master_version_id != a.latest_version_id THEN 'MODIFIED' WHEN EXISTS ( SELECT 1 FROM squad_chat.sq_agent_release_subagent rs JOIN squad_chat.sq_agent sub ON sub.agent_id = rs.subagent_id WHERE rs.release_id = r.release_id AND (sub.deleted_at IS NOT NULL OR sub.latest_version_id != rs.subagent_version_id) ) THEN 'MODIFIED' WHEN EXISTS ( SELECT 1 FROM squad_chat.sq_agent_release_tool rt JOIN squad_chat.sq_tool t ON t.tool_id = rt.tool_id LEFT JOIN squad_chat.sq_mcp_server ms ON ms.mcp_server_id = rt.mcp_server_id WHERE rt.release_id = r.release_id AND ( t.deleted_at IS NOT NULL OR t.latest_version_id != rt.tool_version_id OR (rt.mcp_server_id IS NOT NULL AND (ms.deleted_at IS NOT NULL OR ms.latest_version_id != rt.mcp_server_version_id)) ) ) THEN 'MODIFIED' ELSE 'PUBLISHED' END AS publish_state, ( SELECT count(*) FROM squad_chat.sq_agent_version_tool b WHERE b.agent_version_id = a.latest_version_id ) AS tool_count, ( SELECT count(*) FROM squad_chat.sq_agent_version_subagent d WHERE d.master_version_id = a.latest_version_id ) AS subagent_count, ( SELECT count(DISTINCT m.agent_id) FROM squad_chat.sq_agent m JOIN squad_chat.sq_agent_version_subagent d ON d.master_version_id = m.latest_version_id WHERE m.deleted_at IS NULL AND d.subagent_id = a.agent_id ) AS usage_count, a.last_update_time FROM squad_chat.sq_agent a LEFT JOIN squad_chat.sq_agent_version lv ON lv.agent_version_id = a.latest_version_id LEFT JOIN squad_chat.sq_agent_release r ON r.release_id = a.current_release_id WHERE a.deleted_at IS NULL
AND a.agent_id = #{agentId}
ORDER BY a.last_update_time DESC, a.id DESC
